// ===============================================================================
// DAEMIND SRE - PARSER DE PEDIDO APROVADO
// ===============================================================================
const body = $json.body || $json;

let rawPhone = (body.cliente_whatsapp || body.telefone || body.phone || body.customer?.phone || '').toString().replace(/\D/g, '');
if (rawPhone.length >= 10 && rawPhone.length <= 11) {
  rawPhone = '55' + rawPhone;
}

const clienteNome = (body.cliente_nome || body.nome || body.customer?.first_name || 'Cliente').trim();
const email = (body.cliente_email || body.email || body.customer?.email || '').trim().toLowerCase();
const pedidoId = parseInt(body.pedido_id || body.id || Date.now(), 10);
const numeroPedido = parseInt(body.numero_pedido || body.order_number || pedidoId, 10);
const valorTotal = parseFloat(body.valor_total || body.total || 0);
const produtoPrincipal = (body.produto_nome || body.items?.[0]?.name || 'seu produto').trim();

return [{
  json: {
    pedido_id: pedidoId,
    numero_pedido: numeroPedido,
    cliente_nome: clienteNome,
    whatsapp: rawPhone,
    email: email,
    valor_total: valorTotal,
    produto_principal: produtoPrincipal
  }
}];
